// ---- hooks/src/core.tsx

type Dollar = EngineInterface
type Saved = { marks: BreakpointMark[]; prompts: BreakpointPrompt[] }

const PANE = 'breakpoints'
const TITLE = 'Breakpoints'
const SESSIONS = 'sessions'
const AUTO = 'auto'
const KEEP_SESSIONS = 25
const RECALL_KEEP = 4
// Bumped when labelling changes enough that saved outlines should be redone.
const OUTLINE_VERSION = 2
const BATCH = 40
const MARK_TEXT = /◆ Breakpoint (\d+) · ?([^\n]*)/
// The rows parseTranscript reads: prompts, final answers, compactions, and
// slash commands with what they printed.
const TRANSCRIPT_ROWS = [
  '-e',
  '"origin":{"kind":"human"}',
  '-e',
  '"stop_reason":"end_turn"',
  '-e',
  '"subtype":"compact_boundary"',
  '-e',
  '<command-name>',
  '-e',
  '<local-command-stdout>',
]
const NOT_FULLSCREEN =
  'Jumping needs the fullscreen layout. On the main screen use your terminal scrollback (CLAUDE_CODE_NO_FLICKER=1 turns fullscreen on).'
const OUTLINE_SYSTEM =
  'You keep the outline of a long conversation between a developer and a coding assistant. ' +
  'Titles are plain words naming the task or topic, written like a commit subject: ' +
  'no quotes, no trailing punctuation, no "Chapter" prefix.'

const session = atom({ plugin: 'breakpoints', key: 'session' } as const, '')
const marks = atom({ plugin: 'breakpoints', key: 'marks' } as const, [])
const prompts = atom({ plugin: 'breakpoints', key: 'prompts' } as const, [])
const tab = atom({ plugin: 'breakpoints', key: 'tab' } as const, 'outline')
const filter = atom({ plugin: 'breakpoints', key: 'filter' } as const, '')
const lastJump = atom({ plugin: 'breakpoints', key: 'lastJump' } as const, '')
const auto = atom({ plugin: 'breakpoints', key: 'auto' } as const, true)
const busy = atom({ plugin: 'breakpoints', key: 'busy' } as const, '')
const toggled = atom({ plugin: 'breakpoints', key: 'toggled' } as const, [])
const recall = atom({ plugin: 'breakpoints', key: 'recall' } as const, [])
const isRecalling = atom({ plugin: 'breakpoints', key: 'isRecalling' } as const, false)

// The requestIds the transcript drew rows under, keyed by what the row says,
// tried after the stored row ids in case the two ever differ. Module memory:
// a reload refills it as rows are drawn again.
const markRows = new Map<number, string>()
const promptRows = new Map<string, string>()
const answerRows = new Map<string, string>()

// Model calls run one at a time, off the hook that asked for them.
let queue: Promise<void> = Promise.resolve()

const rowKey = (text: string) => clip(squash(text), PROMPT_CHARS)

const nextId = (list: readonly BreakpointMark[]) => list.reduce((top, one) => Math.max(top, one.id), 0) + 1

function ago(ms: number): string {
  const minutes = Math.floor(ms / 60_000)
  if (minutes < 1) return 'now'
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)

  return hours < 24 ? `${hours}h` : `${Math.floor(hours / 24)}d`
}

// Older saves predate automatic chapters.
const normalise = (one: BreakpointMark): BreakpointMark => ({
  ...one,
  kind: one.kind ?? 'manual',
  anchorText: one.anchorText ?? '',
  after: one.after ?? '',
})

function enqueue($: Dollar, job: () => Promise<void>): void {
  queue = queue.then(job).catch(error => {
    $.ui.log(`breakpoints: ${String(error)}`, { to: 'debug' })
  })
}

const later = ($: Dollar, job: () => Promise<void>) => void $.clock.after(10, () => enqueue($, job))

// Breakpoints belong to one conversation. /clear and /resume swap it under a
// running process, so every entry point checks the id and loads that
// conversation's saved breakpoints when it changed.
async function syncSession($: Dollar): Promise<void> {
  const id = await $.session.id()
  if ((await read($, session)) === id) return

  const saved = (await $.store.get(`s:${id}`)) as Saved | undefined
  await update($, marks, () => (saved?.marks ?? []).map(normalise))
  await update($, prompts, () => saved?.prompts ?? [])
  await update($, lastJump, () => '')
  await update($, toggled, () => [])
  await update($, session, () => id)
  trackingOnSwitch($)
  transcriptOnSwitch($)
}

async function persist($: Dollar): Promise<void> {
  const id = await read($, session)
  if (id === '') return

  const saved: Saved = { marks: await read($, marks), prompts: await read($, prompts) }
  await $.store.set(`s:${id}`, saved)

  const known = ((await $.store.get(SESSIONS)) as string[] | undefined) ?? []
  const order = [id, ...known.filter(one => one !== id)]
  for (const old of order.slice(KEEP_SESSIONS)) {
    await $.store.delete(`s:${old}`)
  }
  await $.store.set(SESSIONS, order.slice(0, KEEP_SESSIONS))
}

// Where Claude Code keeps this conversation: <config>/projects/<dir>/<id>.jsonl,
// <dir> being the start directory with every non-alphanumeric turned into "-".
async function transcriptPath($: Dollar, id: string): Promise<string | undefined> {
  const home = (await $.env.get('HOME')) ?? ''
  const configured = await $.env.get('CLAUDE_CONFIG_DIR')
  const config = (configured ?? `${home}/.claude`).replace(/^~/, home).replace(/\/$/, '')

  for (const dir of new Set([await $.session.root(), await $.session.cwd()])) {
    const path = `${config}/projects/${dir.replace(/[^A-Za-z0-9]/g, '-')}/${id}.jsonl`
    if (await $.fs.exists(path)) return path
  }

  return undefined
}

// The person's prompts and Claude's final answers, read from the transcript
// file: it keeps every row, compacted ones included.
async function readTranscript($: Dollar, id: string): Promise<ReturnType<typeof parseTranscript>> {
  const path = await transcriptPath($, id)
  const run = path === undefined ? undefined : await $.process.run(['grep', '-F', ...TRANSCRIPT_ROWS, path], { timeoutMs: 15_000 })

  return run?.exitCode === 0 ? parseTranscript(run.stdout) : { prompts: [], answers: new Map(), words: new Map(), events: [] }
}

async function askHaiku($: Dollar, prompt: string, maxTokens: number, timeoutMs: number): Promise<string | null> {
  const reply = await $.model.complete({ model: 'haiku', system: OUTLINE_SYSTEM, prompt, maxTokens, effort: 'low', timeoutMs })

  return reply.isAnswered ? reply.text.trim() : null
}

// Pins part of the conversation, word for word, to the person's next message.
async function recallRow($: Dollar, row: OutlineRow): Promise<void> {
  const said = await read($, prompts)
  const all = (await read($, marks)).filter(one => one.isRemoved !== true)
  const after = (mark: BreakpointMark) => said.filter(one => one.uuid === mark.after)
  const [what, glyph, title, scope] =
    row.kind === 'chapter'
      ? ['chapter', '◇', row.mark.label, chapterScope(row.mark, all, said)]
      : row.kind === 'section'
        ? ['sub-topic', '›', row.title, sectionScope(row.prompt, all, said)]
        : row.kind === 'answer'
          ? ['answer', '↳', row.title, [row.prompt]]
          : row.mark.kind === 'auto'
            ? ['chapter', '◇', row.mark.label, chapterScope(row.mark, all, said)]
            : row.mark.kind === 'star'
              ? ['answer', '☆', row.mark.label, after(row.mark)]
              : // A /bp, a compaction or a command: the exchange it came after.
                [
                  row.mark.kind === 'manual' ? 'breakpoint' : `exchange before a ${row.mark.kind === 'compact' ? 'compaction' : 'command'}`,
                  MARK_GLYPH[row.mark.kind],
                  row.mark.label,
                  after(row.mark),
                ]

  const found = await readTranscript($, await read($, session))
  const exchanges = scope.map(prompt => ({
    prompt: found.words.get(prompt.uuid) ?? prompt.text,
    answer: found.answers.get(prompt.uuid)?.text ?? '',
  }))
  if (exchanges.length === 0) {
    $.ui.toast('Nothing to recall there yet.')

    return
  }

  const pinned: BreakpointRecall = {
    key: `${what}:${scope[0]?.uuid ?? ''}`,
    glyph,
    label: title,
    what: exchanges.length > 1 ? `${what}, ${exchanges.length} exchanges` : what,
    text: recallBlock(what, title, exchanges),
  }
  await update($, recall, list => [...list.filter(one => one.key !== pinned.key), pinned].slice(-RECALL_KEEP))
  await update($, isRecalling, () => false)
  await $.ui.close({ id: PANE })

  const box = await $.prompt.read()
  if (box.text.trim() === '') await $.prompt.fill({ text: `Re ${glyph} "${title}": ` })
}

async function jump(
  $: Dollar,
  key: string,
  candidates: readonly string[],
  block: 'start' | 'end',
  isFullscreen: boolean | undefined,
): Promise<void> {
  let reason = 'that part of the conversation has not been drawn'

  for (const requestId of new Set(candidates.filter(one => one !== ''))) {
    try {
      const moved = await $.ui.scroll({ to: { requestId }, block })
      if (moved.deny === undefined) {
        await update($, lastJump, () => key)

        return
      }
      reason = moved.deny
    } catch (error) {
      reason = error instanceof Error ? error.message : String(error)
    }
  }

  $.ui.toast(isFullscreen === false ? NOT_FULLSCREEN : `Could not jump there: ${reason}`)
}

// A /bp mark lands its row at the bottom of the screen, showing what led up to
// it; a chapter, a sub-topic and an answer land at the top. A compaction or a
// command lands its own row at the top, or else the prompt that came after it.
async function jumpToMark($: Dollar, mark: BreakpointMark, isFullscreen: boolean | undefined): Promise<void> {
  if (mark.kind === 'compact' || mark.kind === 'command') {
    const next = promptAfter(await read($, prompts), mark.after)

    return jump($, `mark:${mark.id}`, [mark.anchor, next?.uuid ?? ''], 'start', isFullscreen)
  }

  return mark.kind === 'auto'
    ? jump($, `mark:${mark.id}`, [mark.anchor, promptRows.get(mark.anchorText) ?? ''], 'start', isFullscreen)
    : mark.kind === 'star'
      ? jump($, `mark:${mark.id}`, [mark.anchor, answerRows.get(mark.anchorText) ?? ''], 'start', isFullscreen)
      : jump($, `mark:${mark.id}`, [markRows.get(mark.id) ?? '', mark.anchor], 'end', isFullscreen)
}

const jumpToPrompt = ($: Dollar, prompt: BreakpointPrompt, isFullscreen: boolean | undefined) =>
  jump($, `prompt:${prompt.uuid}`, [prompt.uuid, promptRows.get(prompt.text) ?? ''], 'start', isFullscreen)

const jumpToAnswer = ($: Dollar, prompt: BreakpointPrompt, isFullscreen: boolean | undefined) =>
  jump(
    $,
    `answer:${prompt.uuid}`,
    [prompt.answer ?? '', answerRows.get(prompt.answerText ?? '') ?? ''],
    'start',
    isFullscreen,
  )

// ---- hooks/src/tracking.tsx

const caughtUp = new Set<string>()

// The last text Claude wrote in the main conversation: at the end of a turn,
// that turn's answer.
let latestAnswer: FoundAnswer | undefined

// A re-read of the transcript for compactions and commands is waiting.
let isEventReadPending = false

// Compactions become breakpoints and slash commands hints, read from the
// transcript file (`events`, when the caller has read it already).
async function refreshEvents($: Dollar, events?: readonly FoundEvent[]): Promise<void> {
  const id = await read($, session)
  if (id === '') return
  const found = events ?? (await readTranscript($, id)).events
  if (found.length === 0) return

  let isChanged = false
  await update($, marks, list => {
    const next = withEvents(list, found)
    isChanged = next !== list

    return isChanged ? [...next] : list
  })
  if (isChanged) await persist($)
}

// Rows reach the file a moment after they are appended, so the read waits;
// several rows in a row (a command and what it printed) share one read.
function refreshEventsSoon($: Dollar, delayMs: number): void {
  if (isEventReadPending) return
  isEventReadPending = true
  void $.clock.after(delayMs, () =>
    enqueue($, async () => {
      isEventReadPending = false
      await refreshEvents($)
    }),
  )
}

// Prompts and answers from before the mod was loaded (or in a resumed
// conversation it never saw) are read back from the transcript file, so the
// outline covers the whole conversation. Answers it found, by prompt.
async function backfill($: Dollar, id: string): Promise<Map<string, string>> {
  const found = await readTranscript($, id)
  if (found.prompts.length === 0) return new Map()

  await update($, prompts, list => {
    const recorded = new Map(list.map(one => [one.uuid, one]))
    const known = new Set(found.prompts.map(one => one.uuid))
    const merged = [
      ...found.prompts.map(one => {
        const answer = found.answers.get(one.uuid)
        const fromFile = answer ? { answer: answer.uuid, answerText: rowKey(answer.text) } : {}

        return { ...fromFile, ...one, ...recorded.get(one.uuid) }
      }),
      ...list.filter(one => !known.has(one.uuid)),
    ]

    return merged.map((one, index) => ({ ...one, n: index + 1 }))
  })
  await persist($)
  await refreshEvents($, found.events)

  return new Map([...found.answers].map(([uuid, answer]) => [uuid, answer.text]))
}

async function applyLabels(
  $: Dollar,
  batch: readonly BreakpointPrompt[],
  labels: readonly Label[],
  hasNoChapter: boolean,
): Promise<void> {
  const byN = new Map(labels.map(one => [one.n, one]))
  const at = await $.clock.now()
  const opened: { prompt: BreakpointPrompt; label: string }[] = []

  for (const [index, prompt] of batch.entries()) {
    // Titled before, and answered again since: only its answer is summarised anew.
    if (prompt.title !== undefined) continue
    const label = byN.get(prompt.n)
    const section = label?.section ?? clip(prompt.text, 48)
    const chapter = label?.chapter || (hasNoChapter && index === 0 ? section || clip(prompt.text, 40) : '')
    if (chapter !== '') opened.push({ prompt, label: chapter })
  }

  await update($, prompts, list =>
    list.map(one => {
      if (!batch.some(prompt => prompt.uuid === one.uuid)) return one
      const label = byN.get(one.n)
      const title = one.title ?? (label ? label.section : clip(one.text, 48))
      const answer = label?.answer ?? ''

      return { ...one, title, ...(answer === '' ? {} : { answerTitle: answer }), isLabelled: true }
    }),
  )
  const said = await read($, prompts)
  await update($, marks, list => {
    const next = [...list]
    for (const { prompt, label } of opened) {
      if (next.some(one => one.kind === 'auto' && one.anchor === prompt.uuid)) continue
      const current = chapterBefore(next, said, prompt.uuid)
      if (current !== undefined && isSameTitle(current.label, label)) continue
      next.push({ id: nextId(next), kind: 'auto', label, anchor: prompt.uuid, anchorText: prompt.text, after: '', at })
    }

    return next
  })
  await persist($)
}

// Titles a run of exchanges in one call. A reply that skips or merges an
// exchange is not trusted: the run is halved and each half asked again, down
// to one exchange, which a reply cannot misnumber.
async function labelBatch($: Dollar, batch: readonly BreakpointPrompt[], answers: ReadonlyMap<string, string>): Promise<boolean> {
  const said = await read($, prompts)
  const first = said.findIndex(one => one.uuid === batch[0]?.uuid)
  const before = said.slice(0, Math.max(0, first))
  const chapters = (await read($, marks)).filter(one => one.kind === 'auto' && one.isRemoved !== true)
  const chapter = [...before]
    .reverse()
    .map(one => chapters.find(mark => mark.anchor === one.uuid))
    .find(one => one !== undefined)
  const recent = before.flatMap(one => (one.title ? [one.title] : [])).slice(-3)

  const reply = await askHaiku($, labelRequest(chapter?.label ?? '', recent, batch, answers), 60 * batch.length + 200, 120_000)
  if (reply === null) return false

  const labels = parseLabels(reply).filter(one => batch.some(prompt => prompt.n === one.n))
  if (!isComplete(batch, labels) && batch.length > 1) {
    const half = Math.ceil(batch.length / 2)

    return (await labelBatch($, batch.slice(0, half), answers)) && labelBatch($, batch.slice(half), answers)
  }

  await applyLabels($, batch, labels, chapter === undefined)

  return true
}

// Titles every exchange not yet in the outline: its chapter (new or not), its
// sub-topic (or none, for a follow-up) and a line on what Claude answered.
async function labelPending($: Dollar, answers: ReadonlyMap<string, string>): Promise<void> {
  if (!(await read($, auto))) return
  const pending = (await read($, prompts)).filter(one => one.isLabelled !== true)
  if (pending.length === 0) return

  if (pending.length > 1) await update($, busy, () => `Outlining ${pending.length} prompts…`)
  try {
    for (let start = 0; start < pending.length; start += BATCH) {
      if (!(await labelBatch($, pending.slice(start, start + BATCH), answers))) return
    }
  } finally {
    await update($, busy, () => '')
  }
}

// Forgets every title and chapter the model gave, so the next labelling
// redoes the whole outline. Your own /bp marks stay.
async function resetOutline($: Dollar): Promise<void> {
  await update($, prompts, list =>
    list.map(({ title, answerTitle, isLabelled, ...rest }) => rest),
  )
  await update($, marks, list => list.filter(one => one.kind !== 'auto'))
  await persist($)
}

async function catchUp($: Dollar): Promise<void> {
  const id = await $.session.id()
  if (caughtUp.has(id)) return
  caughtUp.add(id)

  const answers = await backfill($, id)

  // Chapters found before outlines existed, or by an older way of labelling,
  // are redone.
  const version = Number((await $.store.get(`v:${id}`)) ?? 0)
  const said = await read($, prompts)
  if (version < OUTLINE_VERSION || !said.some(one => one.isLabelled === true)) {
    await resetOutline($)
    await $.store.set(`v:${id}`, OUTLINE_VERSION)
  }

  // An answer that arrived after its exchange was titled has no summary yet.
  await update($, prompts, list =>
    list.map(one => {
      if (one.isLabelled !== true || one.answer === undefined || one.answerTitle !== undefined) return one
      const { isLabelled, ...rest } = one

      return rest
    }),
  )

  const repeated = repeatedChapters(await read($, marks), await read($, prompts))
  if (repeated.length > 0) {
    await update($, marks, list => list.map(one => (repeated.includes(one.id) ? { ...one, isRemoved: true } : one)))
    await persist($)
  }
  await labelPending($, answers)
}

// The end of a turn: the prompt that started it gets its answer, and anything
// not yet in the outline is titled.
async function afterTurn($: Dollar, answer: FoundAnswer | undefined): Promise<void> {
  await syncSession($)
  const latest = (await read($, prompts)).at(-1)
  if (latest === undefined) return

  if (answer !== undefined && answer.uuid !== latest.answer) {
    await update($, prompts, list =>
      list.map(one => {
        if (one.uuid !== latest.uuid) return one
        // A later turn (a background task's report) answered again: the old
        // summary no longer describes it, so the answer is summarised again.
        // The title and chapter stay.
        const { answerTitle, isLabelled, ...rest } = one

        return { ...rest, answer: answer.uuid, answerText: rowKey(answer.text) }
      }),
    )
    await persist($)
  }

  await refreshEvents($)
  await labelPending($, new Map(answer ? [[latest.uuid, answer.text]] : []))
}

// The conversation in view changed (the first sync, a /clear, a /resume).
function trackingOnSwitch($: Dollar): void {
  latestAnswer = undefined
  later($, () => catchUp($))
}

async function trackingOnStart($: Dollar): Promise<void> {
  const stored = await $.store.get(AUTO)
  await update($, auto, () => stored !== false)
  await syncSession($)
  later($, () => catchUp($))
}

function trackingOnEnd($: Dollar, e: SessionEndInput): void {
  if (e.reason === 'clear' || e.reason === 'resume') {
    markRows.clear()
    promptRows.clear()
    answerRows.clear()
    void $.clock.after(1000, () => syncSession($))
  }
}

function trackingOnTurn($: Dollar, e: TurnCompleteInput): void {
  if (e.agentId === undefined && e.reason === 'answer') {
    const answer = latestAnswer
    later($, () => afterTurn($, answer))
  }
}

const registerTracking = (on: On) => {
  // Every prompt the person sends is a stop in the outline.
  on('session.append', { door: 'prompt' }, async ($, e, next) => {
    const stored = await next(e)
    const isPersons = e.origin.kind === 'composer' || e.origin.kind === 'bridge'

    if (stored.uuid === undefined || e.agentId !== undefined || e.message.isMeta === true || !isPersons) {
      return stored
    }

    try {
      await syncSession($)
      latestAnswer = undefined
      const uuid = stored.uuid
      const text = rowKey(textOf(stored.message.content)) || '(no text)'
      const at = await $.clock.now()
      await update($, prompts, list =>
        list.some(one => one.uuid === uuid) ? list : [...list, { uuid, text, at, n: (list.at(-1)?.n ?? 0) + 1 }],
      )
      await persist($)
    } catch (error) {
      $.ui.log(`breakpoints: could not record a prompt: ${String(error)}`, { to: 'debug' })
    }

    return stored
  })

  // Claude's text in the main conversation; the last of a turn is its answer.
  on('session.append', { door: 'response' }, async ($, e, next) => {
    const stored = await next(e)
    const text = stored.uuid === undefined ? '' : squash(textOf(stored.message.content))

    if (stored.uuid !== undefined && e.agentId === undefined && text !== '') {
      latestAnswer = { uuid: stored.uuid, text }
    }

    return stored
  })

  // The /bp output row is the breakpoint's anchor: keep the id it was stored
  // under. Any other command is a hint in the outline, read from the file.
  on('session.append', { door: 'command' }, async ($, e, next) => {
    const stored = await next(e)
    if (e.agentId === undefined) refreshEventsSoon($, 1500)
    const found = stored.uuid === undefined ? null : MARK_TEXT.exec(textOf(stored.message.content))

    if (found === null || stored.uuid === undefined || e.agentId !== undefined) {
      return stored
    }

    try {
      const id = Number(found[1])
      const uuid = stored.uuid
      await update($, marks, list =>
        list.map(one => (one.id === id && one.kind === 'manual' && one.anchor === '' ? { ...one, anchor: uuid } : one)),
      )
      await persist($)
    } catch (error) {
      $.ui.log(`breakpoints: could not anchor a breakpoint: ${String(error)}`, { to: 'debug' })
    }

    return stored
  })
}

// ---- hooks/src/transcript.tsx

const foldedChapters = atom({ plugin: 'breakpoints', key: 'folded' } as const, [])
const foldStyleSetting = atom({ plugin: 'breakpoints', key: 'foldStyle' } as const, 'heading')
const readingMode = atom({ plugin: 'breakpoints', key: 'isReading' } as const, false)
const foldedTopics = atom({ plugin: 'breakpoints', key: 'foldedTopics' } as const, [])
const renamingChapter = atom({ plugin: 'breakpoints', key: 'renaming' } as const, 0)
const editingChapters = atom({ plugin: 'breakpoints', key: 'isEditing' } as const, false)

const READING = 'reading'
const FOLD_STYLE = 'foldStyle'
const FOLD_WORDS = ['fold', 'unfold', 'reading', 'fold-style']
const PRESENTATION = 'presentation'
// Every action in the conversation draws the same way: a bracketed button, an
// icon and a word, dim until pointed at. A terminal cell cannot be drawn
// larger, so the word is what makes them easy to spot and to hit.
const ACTIONS = {
  fold: '▼ Fold',
  unfold: '▶ Unfold',
  recall: '↩ Recall',
  rename: '✎ Rename',
  remove: '✕ Remove',
  star: '☆ Star',
  starred: '★ Starred',
}

// Which prompt each transcript row belongs to: row id (a message uuid or a
// tool_use_id) to prompt uuid. Rows added while the mod runs are filed as they
// are appended; older rows are read from the transcript file the first time
// folding or reading mode needs them. Module memory: a reload reads the file
// again, which takes a few milliseconds.
const foldOwners = new Map<string, string>()
// Claude's text blocks by what they say, in case a row is drawn under an id
// other than the uuid it was stored under.
const foldTextOwners = new Map<string, string>()
const foldFiled = new Set<string>()
let foldCurrent: string | undefined

function foldOwnerOf(id: string, text?: string): string | undefined {
  return foldOwners.get(id) ?? (text === undefined ? undefined : foldTextOwners.get(rowKey(text)))
}

// The prompt a row hands its owner to: the last one the person sent.
async function foldCurrentPrompt($: Dollar): Promise<string | undefined> {
  if (foldCurrent === undefined) foldCurrent = (await read($, prompts)).at(-1)?.uuid

  return foldCurrent
}

// Files every row of the transcript under its prompt, once per conversation.
async function foldFileOwners($: Dollar): Promise<void> {
  const id = await read($, session)
  if (id === '' || foldFiled.has(id)) return

  const path = await transcriptPath($, id)
  if (path === undefined) return

  const patterns = OWNER_PATTERNS.flatMap(pattern => ['-e', pattern])
  const run = await $.process.run(['grep', '-n', '-o', '-E', ...patterns, path], { timeoutMs: 15_000 })
  if (run.exitCode !== 0) return

  const known = new Set((await read($, prompts)).map(one => one.uuid))
  for (const [row, owner] of parseOwners(run.stdout, known)) {
    if (!foldOwners.has(row)) foldOwners.set(row, owner)
  }
  foldFiled.add(id)
}

// Called from main's session.start: reading mode and the fold style are
// preferences kept across sessions; folds already set (a reload) need the
// rows filed again before they can hide anything.
async function transcriptOnStart($: Dollar): Promise<void> {
  const reading = await $.store.get(READING)
  const style = await $.store.get(FOLD_STYLE)
  await update($, readingMode, () => reading === true)
  await update($, foldStyleSetting, () => (style === 'summary' ? 'summary' : 'heading'))

  if (reading === true || (await read($, foldedChapters)).length > 0) {
    later($, () => foldRefile($))
  }
}

// Called from core's syncSession: another conversation is in view.
function transcriptOnSwitch($: Dollar): void {
  foldOwners.clear()
  foldTextOwners.clear()
  foldCurrent = undefined
  later($, () => foldReset($))
}

async function foldReset($: Dollar): Promise<void> {
  await update($, foldedChapters, () => [])
  await update($, foldedTopics, () => [])
  if (await read($, readingMode)) await foldRefile($)
}

// Files the rows, then draws every hooked row again with the owners known.
async function foldRefile($: Dollar): Promise<void> {
  await foldFileOwners($)
  await update($, foldedChapters, list => [...list])
}

async function foldSet($: Dollar, ids: readonly number[], isFolded: boolean): Promise<void> {
  if (isFolded) await foldFileOwners($)
  await update($, foldedChapters, list =>
    isFolded ? [...new Set([...list, ...ids])] : list.filter(one => !ids.includes(one)),
  )
  if (isFolded && (await read($, foldStyleSetting)) === 'summary') later($, () => foldSummarise($))
}

// A two-line summary for every folded chapter that has none yet.
async function foldSummarise($: Dollar): Promise<void> {
  const folded = await read($, foldedChapters)
  const said = await read($, prompts)
  const all = await read($, marks)
  const missing = all.filter(one => folded.includes(one.id) && one.kind === 'auto' && !one.summary)
  if (missing.length === 0) return

  const found = await readTranscript($, await read($, session))
  for (const mark of missing) {
    const scope = foldView(all, said, [mark.id]).scopes.get(mark.id) ?? []
    const exchanges = scope.map(prompt => ({
      prompt: found.words.get(prompt.uuid) ?? prompt.text,
      answer: found.answers.get(prompt.uuid)?.text ?? '',
    }))
    const reply = await askHaiku($, summaryRequest(mark.label, exchanges), 160, 60_000)
    if (reply === null) return

    const summary = summaryLines(reply).join('\n')
    await update($, marks, list => list.map(one => (one.id === mark.id ? { ...one, summary } : one)))
    await persist($)
  }
}

async function foldSetReading($: Dollar, isOn: boolean): Promise<void> {
  if (isOn) await foldFileOwners($)
  await update($, readingMode, () => isOn)
  await $.store.set(READING, isOn)
}

async function foldToggleStar($: Dollar, prompt: BreakpointPrompt, rowId: string, text: string): Promise<void> {
  const key = rowKey(text)
  const at = await $.clock.now()

  await update($, marks, list => {
    const kept = list.find(one => one.kind === 'star' && one.after === prompt.uuid && (one.anchor === rowId || one.anchorText === key))
    if (kept !== undefined) return list.map(one => (one === kept ? { ...one, isRemoved: one.isRemoved !== true } : one))

    const star: BreakpointMark = {
      id: nextId(list),
      kind: 'star',
      label: prompt.answerTitle ?? clip(squash(text), 60),
      anchor: prompt.answer ?? rowId,
      anchorText: key,
      after: prompt.uuid,
      at,
    }

    return [...list, star]
  })
  await persist($)
}

// Tool calls made by the exchanges a fold holds.
function foldToolCount(scope: readonly BreakpointPrompt[]): number {
  const inScope = new Set(scope.map(one => one.uuid))

  return [...foldOwners].filter(([row, owner]) => row.startsWith('toolu_') && inScope.has(owner)).length
}

// A sub-topic's Fold / Unfold on its prompt row.
async function foldTopic($: Dollar, uuid: string, isFolded: boolean): Promise<void> {
  if (isFolded) await foldFileOwners($)
  await update($, foldedTopics, list => (isFolded ? [...new Set([...list, uuid])] : list.filter(one => one !== uuid)))
}

// A /bp's Fold: fold what follows it, or say there is nothing yet.
async function foldBreakpoint($: Dollar, mark: BreakpointMark): Promise<void> {
  const scope = breakpointScope(mark, await read($, marks), await read($, prompts))
  if (scope.length === 0) {
    $.ui.toast('Nothing after this breakpoint to fold yet.')

    return
  }
  await foldSet($, [mark.id], true)
}

async function foldRemoveMark($: Dollar, id: number): Promise<void> {
  await update($, marks, list => list.map(one => (one.id === id ? { ...one, isRemoved: true } : one)))
  await persist($)
}

async function foldRename($: Dollar, mark: BreakpointMark): Promise<void> {
  await update($, renamingChapter, () => mark.id)
  await update($, editingChapters, () => true)
  await $.ui.open({ id: PANE, title: TITLE, focus: true, closeOnEscape: true })
}

// What the hooks below need to decide a row: the folds and reading mode, and
// (only when one is on) the outline they apply to.
async function foldContext($: Dollar): Promise<{ view: FoldView; isReading: boolean; said: readonly BreakpointPrompt[] } | null> {
  const folded = await read($, foldedChapters)
  const topics = await read($, foldedTopics)
  const isReading = await read($, readingMode)
  if (folded.length === 0 && topics.length === 0 && !isReading) return null

  const said = await read($, prompts)
  const view = foldView(await read($, marks), said, folded, topics)

  return { view, isReading, said }
}

async function foldIsShown($: Dollar, kind: RowKind, owner: string | undefined, isFinal = false): Promise<boolean> {
  const context = await foldContext($)
  if (context === null) return true

  const prompt = owner === undefined ? undefined : context.said.find(one => one.uuid === owner)
  const reading = { isOn: context.isReading, isAnswered: prompt?.answer !== undefined, isFinal }

  return isRowShown(kind, owner, context.view, reading)
}

const registerTranscript = (on: On) => {
  // Rows are filed under the prompt above them as the conversation grows.
  on('session.append', { door: 'prompt' }, async ($, e, next) => {
    const stored = await next(e)
    const isPersons = e.origin.kind === 'composer' || e.origin.kind === 'bridge'

    if (stored.uuid !== undefined && e.agentId === undefined && e.message.isMeta !== true && isPersons) {
      foldCurrent = stored.uuid
      foldOwners.set(stored.uuid, stored.uuid)
    }

    return stored
  })

  on('session.append', { door: 'response' }, async ($, e, next) => {
    const stored = await next(e)
    const owner = stored.uuid === undefined || e.agentId !== undefined ? undefined : await foldCurrentPrompt($)
    if (owner === undefined || stored.uuid === undefined) return stored

    foldOwners.set(stored.uuid, owner)
    for (const block of stored.message.content as readonly unknown[]) {
      const one = block as { type?: unknown; id?: unknown }
      if (one.type === 'tool_use' && typeof one.id === 'string') foldOwners.set(one.id, owner)
    }
    const text = textOf(stored.message.content)
    if (text.trim() !== '') foldTextOwners.set(rowKey(text), owner)

    return stored
  })

  on('session.append', { door: 'command' }, async ($, e, next) => {
    const stored = await next(e)
    const owner = stored.uuid === undefined || e.agentId !== undefined ? undefined : await foldCurrentPrompt($)
    if (owner !== undefined && stored.uuid !== undefined) foldOwners.set(stored.uuid, owner)

    return stored
  })

  on('session.append', { door: 'notice' }, async ($, e, next) => {
    const stored = await next(e)
    const owner = stored.uuid === undefined || e.agentId !== undefined ? undefined : await foldCurrentPrompt($)
    if (owner !== undefined && stored.uuid !== undefined) foldOwners.set(stored.uuid, owner)

    return stored
  })

  // `/bps fold [n|all|others]`, `/bps unfold [n|all]`, `/bps reading`,
  // `/bps fold-style heading|summary`; anything else goes on to the panel.
  on('command.run', { command: 'bps' }, async ($, e, next) => {
    // Clicks inside the conversation need the fullscreen layout: keep what this
    // terminal reported, to tell "nothing happens on click" apart from a bug.
    await $.store.set(PRESENTATION, e.presentation)
    const [word = '', target = ''] = squash(e.args).toLowerCase().split(' ')
    if (!FOLD_WORDS.includes(word)) return next(e)

    await syncSession($)
    if (word === 'reading') {
      const isOn = !(await read($, readingMode))
      await foldSetReading($, isOn)

      return { text: isOn ? 'Reading mode on: prompts and final answers only.' : 'Reading mode off.' }
    }
    if (word === 'fold-style') {
      if (target !== 'heading' && target !== 'summary') return { text: 'Use /bps fold-style heading or /bps fold-style summary.' }
      await update($, foldStyleSetting, () => target)
      await $.store.set(FOLD_STYLE, target)
      if (target === 'summary') later($, () => foldSummarise($))

      return { text: `Folded chapters now show ${target === 'summary' ? 'a two-line summary' : 'their heading only'}.` }
    }

    const chapters = chapterList(await read($, marks), await read($, prompts))
    const isEverything = word === 'unfold' && (target === '' || target === 'all')
    const ids = isEverything ? await read($, foldedChapters) : foldTargets(target, chapters)
    if (typeof ids === 'string') return { text: ids }

    await foldSet($, ids, word === 'fold')
    const count = `${ids.length} chapter${ids.length === 1 ? '' : 's'}`
    if (isEverything) {
      const topics = await read($, foldedTopics)
      await update($, foldedTopics, () => [])

      return { text: ids.length + topics.length === 0 ? 'Nothing is folded.' : 'Unfolded everything.' }
    }

    return { text: word === 'fold' ? `Folded ${count}.` : `Unfolded ${count}.` }
  })

  // The /bp row in the transcript: a magenta rule so it stands out when scrolling by.
  on('ui.render', { component: 'CommandOutput', props: { command: 'bp' } }, async ($, e, next) => {
    const found = MARK_TEXT.exec(e.props.text)
    if (found === null || e.props.isErrored) return next(e)

    const id = Number(found[1])
    markRows.set(id, e.requestId)

    const { Box, Text, Button } = $.ui.resolve(e)
    if (!(await foldIsShown($, 'command', foldOwnerOf(e.requestId)))) return <Box display="none" />

    const all = await read($, marks)
    const mark = all.find(one => one.id === id && one.kind === 'manual')
    const label = mark?.label ?? squash((found[2] ?? '').replace(/<\/[^>]*>\s*$/, ''))
    const isRemoved = mark?.isRemoved === true
    const width = Math.max(24, (e.viewport?.columns ?? 80) - 2)
    const isFolded = mark !== undefined && !isRemoved && (await read($, foldedChapters)).includes(mark.id)
    const controls = mark !== undefined && !isRemoved && (
      <Box flexDirection="row" gap={1}>
        <Button key="bp-recall" dimColor label={ACTIONS.recall} onPress={() => recallRow($, { kind: 'mark', mark, isNested: false })} />
        <Button key="bp-remove" dimColor label={ACTIONS.remove} onPress={() => foldRemoveMark($, mark.id)} />
      </Box>
    )

    if (isFolded) {
      const said = await read($, prompts)
      const scope = foldView(all, said, [mark.id]).scopes.get(mark.id) ?? []
      const tools = foldToolCount(scope)

      return (
        <Box flexDirection="row" gap={1}>
          <Button key="bp-fold" dimColor label={ACTIONS.unfold} onPress={() => foldSet($, [mark.id], false)} />
          <Text color="magenta" bold wrap="truncate-end">
            {`◆ ${clip(foldedLine(mark, scope.length, tools), Math.max(16, width - 52))}`}
          </Text>
          {controls}
        </Box>
      )
    }

    const body = clip(isRemoved ? `${label} (removed)` : label, Math.max(8, width - 52))
    const rule = '─'.repeat(Math.max(2, width - body.length - 48))

    return (
      <Box flexDirection="row" gap={1}>
        {mark !== undefined && !isRemoved && (
          <Button key="bp-fold" dimColor label={ACTIONS.fold} onPress={() => foldBreakpoint($, mark)} />
        )}
        <Text color="magenta" bold dimColor={isRemoved} wrap="truncate-end">
          {`◆ ${body}`}
        </Text>
        <Text color="magenta" dimColor wrap="truncate-end">
          {rule}
        </Text>
        {controls}
      </Box>
    )
  })

  // Any other command's output belongs to its prompt, and folds with it.
  on('ui.render', { component: 'CommandOutput' }, async ($, e, next) => {
    if (e.props.command === 'bp') return next(e)
    if (await foldIsShown($, 'command', foldOwnerOf(e.requestId))) return next(e)
    const { Box } = $.ui.resolve(e)

    return <Box display="none" />
  })

  // A prompt that opens a chapter gets the chapter's title drawn above it,
  // with its controls; a folded chapter draws as that one line.
  on('ui.render', { component: 'UserMessage' }, async ($, e, next) => {
    if (e.props.origin.kind !== 'composer' && e.props.origin.kind !== 'bridge') return next(e)

    const key = rowKey(e.props.text)
    promptRows.set(key, e.requestId)

    const all = await read($, marks)
    const said = await read($, prompts)
    const prompt = said.find(one => one.uuid === e.requestId) ?? said.find(one => one.text === key)
    const chapter = all.find(
      one =>
        one.kind === 'auto' &&
        one.isRemoved !== true &&
        (one.anchor === e.requestId || (one.anchorText !== '' && one.anchorText === key)),
    )
    const folded = await read($, foldedChapters)
    const topics = await read($, foldedTopics)
    const { Box, Text, Button } = $.ui.resolve(e)
    const width = Math.max(24, (e.viewport?.columns ?? 80) - 2)
    let topicLine: RenderElement | undefined

    if (!e.props.isExpanded && prompt !== undefined && (folded.length > 0 || topics.length > 0)) {
      const view = foldView(all, said, folded, topics)
      const opens = view.openers.get(prompt.uuid)

      if (opens !== undefined) {
        const scope = view.scopes.get(opens.id) ?? []
        const tools = foldToolCount(scope)
        const style = await read($, foldStyleSetting)
        const summary = style === 'summary' ? summaryLines(opens.summary ?? '') : []

        return (
          <Box flexDirection="column" marginTop={1}>
            <Box flexDirection="row" gap={1}>
              <Button key="fold-open" dimColor label={ACTIONS.unfold} onPress={() => foldSet($, [opens.id], false)} />
              <Text color="cyan" bold wrap="truncate-end">
                {`◇ ${clip(foldedLine(opens, scope.length, tools), Math.max(16, width - 52))}`}
              </Text>
              <Button
                key="fold-recall"
                dimColor
                label={ACTIONS.recall}
                onPress={() => recallRow($, { kind: 'chapter', mark: opens, isOpen: false, sections: 0 })}
              />
              <Button key="fold-rename" dimColor label={ACTIONS.rename} onPress={() => foldRename($, opens)} />
            </Box>
            {summary.map(line => (
              <Text dimColor wrap="truncate-end">
                {`    ${line}`}
              </Text>
            ))}
            {style === 'summary' && summary.length === 0 && <Text dimColor>    Summing up…</Text>}
          </Box>
        )
      }
      if (view.hidden.has(prompt.uuid) || view.topicHidden.has(prompt.uuid)) return <Box display="none" />

      const scope = view.topics.get(prompt.uuid)
      if (scope !== undefined) {
        const title = prompt.title || clip(prompt.text, 60)
        const answer = [...scope].reverse().find(one => one.answerTitle !== undefined)?.answerTitle

        topicLine = (
          <Box flexDirection="column" marginTop={1}>
            <Box flexDirection="row" gap={1}>
              <Button key="topic-open" dimColor label={ACTIONS.unfold} onPress={() => foldTopic($, prompt.uuid, false)} />
              <Text bold wrap="truncate-end">
                {`› ${clip(foldedTopicLine(title, scope, foldToolCount(scope)), Math.max(16, width - 36))}`}
              </Text>
              <Button
                key="topic-recall"
                dimColor
                label={ACTIONS.recall}
                onPress={() => recallRow($, { kind: 'section', prompt, title, isNested: false })}
              />
            </Box>
            {answer !== undefined && (
              <Text color="green" dimColor wrap="truncate-end">
                {`    ↳ ${answer}`}
              </Text>
            )}
          </Box>
        )
      }
    }

    // Every sub-topic's prompt gets a Fold button that folds the exchange where it stands.
    const hasArrow = !e.props.isExpanded && prompt !== undefined && opensTopic(prompt, chapter !== undefined)
    const row = async (): Promise<RenderElement> =>
      topicLine ??
      (hasArrow && prompt !== undefined ? (
        <Box flexDirection="row">
          <Button key="topic-fold" dimColor label={ACTIONS.fold} onPress={() => foldTopic($, prompt.uuid, true)} />
          <Box flexDirection="column" flexGrow={1} marginLeft={1}>
            {await next(e)}
          </Box>
        </Box>
      ) : (
        await next(e)
      ))

    if (chapter === undefined) return row()

    const title = clip(chapter.label, Math.max(8, width - 56))
    const heading: RenderElement = (
      <Box flexDirection="row" marginTop={1} gap={1}>
        <Button key="fold-close" dimColor label={ACTIONS.fold} onPress={() => foldSet($, [chapter.id], true)} />
        <Text color="cyan" bold wrap="truncate-end">
          {`◇ ${title}`}
        </Text>
        <Text color="cyan" dimColor wrap="truncate-end">
          {'─'.repeat(Math.max(2, width - title.length - 52))}
        </Text>
        <Button
          key="fold-recall"
          dimColor
          label={ACTIONS.recall}
          onPress={() => recallRow($, { kind: 'chapter', mark: chapter, isOpen: true, sections: 0 })}
        />
        <Button key="fold-rename" dimColor label={ACTIONS.rename} onPress={() => foldRename($, chapter)} />
      </Box>
    )

    return (
      <Box flexDirection="column">
        {heading}
        {await row()}
      </Box>
    )
  })

  // Claude's text. A final answer gets a Star that keeps it as a breakpoint; in
  // reading mode the text in between goes; in a folded chapter all of it does.
  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    if (e.props.text === '') return next(e)
    const key = rowKey(e.props.text)
    answerRows.set(key, e.requestId)

    const said = await read($, prompts)
    const answered = said.find(one => one.answer === e.requestId) ?? said.find(one => one.answerText === key)
    const owner = foldOwnerOf(e.requestId, e.props.text) ?? answered?.uuid
    const { Box, Button } = $.ui.resolve(e)
    if (!(await foldIsShown($, 'text', owner, answered !== undefined))) return <Box display="none" />
    if (answered === undefined) return next(e)

    const isStarred = (await read($, marks)).some(
      one => one.kind === 'star' && one.isRemoved !== true && one.after === answered.uuid && (one.anchor === e.requestId || one.anchorText === key),
    )

    const body: RenderElement = (
      <Box flexDirection="column" flexGrow={1}>
        {await next(e)}
        <Box flexDirection="row">
          <Button
            key="star"
            dimColor={!isStarred}
            label={isStarred ? ACTIONS.starred : ACTIONS.star}
            onPress={() => foldToggleStar($, answered, e.requestId, e.props.text)}
          />
        </Box>
      </Box>
    )
    if (!isStarred) return body

    // A starred answer carries a yellow bar down its left edge: a one-column
    // Box with a background, stretched to the answer's whole height.
    return (
      <Box flexDirection="row" alignItems="stretch">
        <Box key="star-bar" width={1} backgroundColor="yellow" />
        <Box flexDirection="column" flexGrow={1} marginLeft={1}>
          {body}
        </Box>
      </Box>
    )
  })

  // Tool rows: hidden in a folded chapter, and in reading mode once their
  // exchange has its answer.
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    if (await foldIsShown($, 'tool', foldOwnerOf(e.props.tool_use_id))) return next(e)
    const { Box } = $.ui.resolve(e)

    return <Box display="none" />
  })

  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    if (await foldIsShown($, 'tool', foldOwnerOf(e.props.tool_use_id))) return next(e)
    const { Box } = $.ui.resolve(e)

    return <Box display="none" />
  })

  on('ui.render', { component: 'ToolGroup' }, async ($, e, next) => {
    const first = e.props.calls.find(one => one.tool_use_id !== undefined)?.tool_use_id
    const owner = first === undefined ? foldOwnerOf(e.requestId) : foldOwnerOf(first)
    if (await foldIsShown($, 'tool', owner)) return next(e)
    const { Box } = $.ui.resolve(e)

    return <Box display="none" />
  })

  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => {
    if (await foldIsShown($, 'duration', foldOwnerOf(e.requestId))) return next(e)
    const { Box } = $.ui.resolve(e)

    return <Box display="none" />
  })
}

// ---- hooks/src/stats.tsx

const STATS_STATUS_EVERY = 5000

// The session's running total at the last turn's end, and the status line as
// last drawn. Module memory: after a reload the next turn starts the reading
// again, and the status is drawn afresh.
let statsLastUsd: number | undefined
let statsShownStatus: string | undefined

// Time and cost per exchange and chapter; the current chapter in the status line.
const registerStats = (on: On) => {
  void on
}

async function statsOnStart($: Dollar): Promise<void> {
  statsShownStatus = undefined
  await statsRefreshStatus($)
  // Chapters change when labelling lands a few seconds after a turn, on a
  // /resume or from the panel; a light poll keeps the line honest.
  void $.clock.every(STATS_STATUS_EVERY, () => void statsRefreshStatus($))
}

function statsOnTurn($: Dollar, e: TurnCompleteInput): void {
  if (e.agentId !== undefined) return
  const { durationMs, usage } = e
  void $.clock.after(10, () => void statsRecordTurn($, durationMs, usage))
}

async function statsRefreshStatus($: Dollar): Promise<void> {
  const text = (await read($, auto)) ? statusText(await read($, marks), await read($, prompts)) : undefined
  if (text === statsShownStatus) return

  statsShownStatus = text
  $.ui.status(text)
}

// Dollars the session spent since the previous turn ended. Before the first
// reading there is nothing to subtract from: on the session's first prompt
// that is $0, otherwise (a resumed session, a reload) the turn goes unpriced.
async function statsSpentSince($: Dollar): Promise<number | undefined> {
  const usd = (await $.session.usage()).cost?.usd
  if (usd === undefined) return undefined

  const before = statsLastUsd ?? ((await $.session.turns()) <= 1 ? 0 : undefined)
  statsLastUsd = usd
  if (before === undefined) return undefined

  // A /clear starts the ledger over.
  return usd >= before ? usd - before : usd
}

// What the turn took goes on the prompt it answered; several turns answering
// one prompt (a background task's report) add up.
async function statsRecordTurn($: Dollar, durationMs: number, usage: TurnUsage | undefined): Promise<void> {
  const latest = (await read($, prompts)).at(-1)
  if (latest === undefined) return

  const spent = await statsSpentSince($)
  const tokens = usageTokens(usage)

  await update($, prompts, list =>
    list.map(one =>
      one.uuid !== latest.uuid
        ? one
        : {
            ...one,
            durationMs: (one.durationMs ?? 0) + durationMs,
            tokens: (one.tokens ?? 0) + tokens,
            ...(spent === undefined ? {} : { costUsd: (one.costUsd ?? 0) + spent }),
          },
    ),
  )
  await persist($)
}

// ---- hooks/src/search.tsx

const SEARCH_PANE = 'bp-search'
// A search reads about 40 MB a second of transcript: the newest files that
// fit both limits are searched, the rest named in the note.
const SEARCH_FILES = 150
const SEARCH_BYTES = 600_000_000
const SEARCH_ROOM = 160
const SEARCH_GLYPH: Record<BreakpointSearchHit['kind'], string> = {
  chapter: '◇',
  topic: '›',
  mark: '◆',
  prompt: '>',
  answer: '↳',
}

const searchQuery = atom({ plugin: 'breakpoints', key: 'searchQuery' } as const, '')
const searchFound = atom({ plugin: 'breakpoints', key: 'searchHits' } as const, [])
const searchBusy = atom({ plugin: 'breakpoints', key: 'isSearching' } as const, false)
const searchNote = atom({ plugin: 'breakpoints', key: 'searchNote' } as const, '')

// The folder Claude Code keeps every project's transcripts in.
async function searchProjectsDir($: Dollar): Promise<string> {
  const home = (await $.env.get('HOME')) ?? ''
  const configured = await $.env.get('CLAUDE_CONFIG_DIR')

  return `${(configured ?? `${home}/.claude`).replace(/^~/, home).replace(/\/$/, '')}/projects`
}

// This project's transcript folders: the start directory's, and the working
// directory's when it differs, each with every non-alphanumeric as "-".
async function searchHereDirs($: Dollar): Promise<string[]> {
  const projects = await searchProjectsDir($)
  const dirs = new Set([await $.session.root(), await $.session.cwd()].map(dir => `${projects}/${dir.replace(/[^A-Za-z0-9]/g, '-')}`))
  const found: string[] = []
  for (const dir of dirs) {
    if (await $.fs.exists(dir)) found.push(dir)
  }

  return found
}

async function searchAllDirs($: Dollar): Promise<string[]> {
  const projects = await searchProjectsDir($)
  let entries: FsEntry[] = []
  try {
    entries = await $.fs.list(projects)
  } catch {
    return []
  }

  return entries.filter(one => one.kind === 'dir').map(one => `${projects}/${one.name}`)
}

// Transcript files in the folders, newest first.
async function searchListFiles($: Dollar, dirs: readonly string[]): Promise<{ path: string; mtime: number; size: number }[]> {
  const files: { path: string; mtime: number; size: number }[] = []
  for (const dir of dirs) {
    let entries: FsEntry[] = []
    try {
      entries = await $.fs.list(dir)
    } catch {
      continue
    }
    for (const one of entries) {
      if (one.kind === 'file' && one.name.endsWith('.jsonl')) {
        files.push({ path: `${dir}/${one.name}`, mtime: one.mtimeMs, size: one.size })
      }
    }
  }

  return files.sort((a, b) => b.mtime - a.mtime)
}

async function searchRun($: Dollar, query: string, isAll: boolean): Promise<void> {
  const words = searchWords(query)
  const word = searchPrefilter(words)
  const current = await $.session.id()
  const root = await $.session.root()
  const hereDirs = await searchHereDirs($)
  const everyFile = await searchListFiles($, isAll ? await searchAllDirs($) : hereDirs)
  let bytes = 0
  const files = everyFile.slice(0, SEARCH_FILES).filter(one => {
    bytes += one.size

    return bytes <= SEARCH_BYTES || one === everyFile[0]
  })
  const isHere = (path: string) => hereDirs.some(dir => path.startsWith(`${dir}/`))

  let found: SearchFile[] = []
  let isCut = false
  if (word !== '' && files.length > 0) {
    const run = await $.process.run(['sh', '-c', SEARCH_SCRIPT, 'sh', word, ...files.map(one => one.path)], { timeoutMs: 60_000 })
    found = parseSearchOutput(run.stdout)
    isCut = run.isStdoutTruncated
  }

  // Whose stored outline may answer: conversations in the folders searched,
  // and this one, whose outline is read live rather than from its last save.
  const places = new Map(files.map(one => [searchSessionOf(one.path), { cwd: isHere(one.path) ? root : '', title: '' }]))
  places.set(current, { cwd: root, title: '' })
  const outlines = new Map<string, SearchSaved>()
  const known = ((await $.store.get(SESSIONS)) as string[] | undefined) ?? []
  for (const id of known) {
    if (!places.has(id) || id === current) continue
    const saved = (await $.store.get(`s:${id}`)) as SearchSaved | undefined
    if (saved !== undefined) outlines.set(id, saved)
  }
  outlines.set(current, { marks: await read($, marks), prompts: await read($, prompts) })

  const here = new Set(files.filter(one => isHere(one.path)).map(one => searchSessionOf(one.path)))
  here.add(current)
  const hits = searchHits({ files: found, outlines, words, places, room: SEARCH_ROOM }).map(hit =>
    here.has(hit.sessionId) ? { ...hit, cwd: root } : hit,
  )

  const scope = isAll ? 'every project' : 'this project'
  const notes = [`${hits.length === 0 ? 'No' : hits.length} hit${hits.length === 1 ? '' : 's'} in ${scope}`]
  if (everyFile.length > files.length) notes.push(`newest ${files.length} of ${everyFile.length} conversations`)
  if (isCut) notes.push('stopped at 4 MB of matches, add a word to narrow it')
  await update($, searchFound, () => hits)
  await update($, searchNote, () => notes.join(' · '))
}

// A hit in this conversation jumps there; one in another fills the prompt with
// /resume, or, in another project, copies the command that resumes it there.
async function searchOpen($: Dollar, hit: BreakpointSearchHit, surface: RenderSurface, isFullscreen: boolean | undefined): Promise<void> {
  if (hit.sessionId === (await $.session.id())) {
    const prompt = (await read($, prompts)).find(one => one.uuid === hit.uuid)
    if (prompt === undefined) {
      $.ui.toast('That part of this conversation is not in its outline yet.')

      return
    }
    if (hit.kind === 'answer') await jumpToAnswer($, prompt, isFullscreen)
    else await jumpToPrompt($, prompt, isFullscreen)

    return
  }

  if (hit.cwd !== (await $.session.root())) {
    const command =
      hit.cwd === ''
        ? `claude --resume ${hit.sessionId}`
        : `cd '${hit.cwd.replace(/'/g, `'\\''`)}' && claude --resume ${hit.sessionId}`
    const copied = await $.ui.copy({ text: command, surface })
    $.ui.toast(
      copied.isCopied
        ? `That conversation is in ${hit.project || 'another project'}: copied the command that resumes it.`
        : `That conversation is in ${hit.project || 'another project'}. Resume it with: ${command}`,
    )

    return
  }

  await $.prompt.fill({ text: `/resume ${hit.sessionId}` })
  await $.ui.close({ id: SEARCH_PANE })
  $.ui.toast(`Press Enter to resume "${clip(hit.title, 40)}".`)
}

const registerSearch = (on: On) => {
  // `/bps search <words>`, `/bps search --all <words>`; every other /bps
  // argument goes on to the panel.
  on('command.run', { command: 'bps' }, async ($, e, next) => {
    const asked = /^search(?:\s+(.*))?$/i.exec(squash(e.args))
    if (asked === null) return next(e)

    const rest = asked[1] ?? ''
    const isAll = /(^|\s)--all(\s|$)/.test(rest)
    const query = squash(rest.replace(/(^|\s)--all(?=\s|$)/g, ' '))
    if (searchWords(query).length === 0) {
      $.ui.toast('Type /bps search <words>, or /bps search --all <words> for every project.')

      return {}
    }

    await syncSession($)
    await update($, searchQuery, () => query)
    await update($, searchFound, () => [])
    await update($, searchNote, () => `Searching ${isAll ? 'every project' : 'this project'}…`)
    await update($, searchBusy, () => true)
    const opened = await $.ui.open({ id: SEARCH_PANE, title: 'Search', focus: true, closeOnEscape: true })
    if (!opened.isPlaced) $.ui.toast(`The search results are waiting for room: ${opened.reason}`)

    try {
      await searchRun($, query, isAll)
    } catch (error) {
      await update($, searchNote, () => `The search failed: ${error instanceof Error ? error.message : String(error)}`)
    } finally {
      await update($, searchBusy, () => false)
    }

    return {}
  })

  on('ui.render', { component: 'Pane', requestId: SEARCH_PANE }, async ($, e) => {
    const { Box, Text, Button } = $.ui.resolve(e)
    const query = await read($, searchQuery)
    const hits = await read($, searchFound)
    const isBusy = await read($, searchBusy)
    const note = await read($, searchNote)
    const current = await read($, session)
    const now = await $.clock.now()
    const width = Math.max(24, e.props.bodyColumns)
    const isFullscreen = e.viewport?.isFullscreen
    const isManyProjects = new Set(hits.map(hit => hit.project)).size > 1

    const groups: { sessionId: string; hits: { hit: BreakpointSearchHit; index: number }[] }[] = []
    for (const [index, hit] of hits.entries()) {
      const group = groups.at(-1)
      if (group !== undefined && group.sessionId === hit.sessionId) group.hits.push({ hit, index })
      else groups.push({ sessionId: hit.sessionId, hits: [{ hit, index }] })
    }

    const drawGroup = (group: (typeof groups)[number]) => {
      const first = group.hits[0]?.hit
      const latest = Math.max(...group.hits.map(one => one.hit.at))
      const where = [
        searchDate(latest, now),
        clip(first?.title || 'Untitled conversation', Math.max(12, width - 30)),
        ...(isManyProjects && first?.project ? [first.project] : []),
        ...(group.sessionId === current ? ['this conversation'] : []),
      ].filter(one => one !== '')

      return (
        <Box key={`group-${group.sessionId}`} flexDirection="column">
          <Text bold color={group.sessionId === current ? 'cyan' : 'white'} wrap="truncate-end">
            {where.join(' · ')}
          </Text>
          {group.hits.map(({ hit, index }) => {
            const chapter = hit.kind !== 'chapter' && hit.chapter !== '' ? `◇ ${clip(hit.chapter, Math.floor(width / 3))}` : ''
            const room = Math.max(8, width - chapter.length - 8)

            return (
              <Box key={`row-hit-${index}`} flexDirection="row">
                <Text color={hit.kind === 'answer' ? 'green' : hit.kind === 'mark' ? 'magenta' : 'cyan'}>
                  {`  ${SEARCH_GLYPH[hit.kind]} `}
                </Text>
                <Button
                  key={`hit-${index}`}
                  plain
                  {...(hit.kind === 'answer' ? { dimColor: true } : {})}
                  label={clip(hit.text, room)}
                  onPress={pressed => searchOpen($, hit, pressed.surface, isFullscreen)}
                />
                <Box flexGrow={1} />
                <Text dimColor>{chapter === '' ? '' : ` ${chapter}`}</Text>
              </Box>
            )
          })}
        </Box>
      )
    }

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Text bold wrap="truncate-end">{`Search: ${clip(query, Math.max(8, width - 16))}`}</Text>
          <Box flexGrow={1} />
          <Button key="search-close" role="dismiss" hotkey="q" dimColor label="Close" onPress={() => $.ui.close({ id: SEARCH_PANE })} />
        </Box>
        <Text dimColor wrap="truncate-end">
          {note}
        </Text>
        <Text dimColor wrap="truncate-end">
          {'─'.repeat(width)}
        </Text>
        {isBusy && <Text color="cyan">Searching…</Text>}
        {!isBusy && hits.length === 0 && <Text dimColor>{`Nothing found for "${clip(query, 40)}".`}</Text>}
        {groups.map(drawGroup)}
        <Text dimColor wrap="truncate-end">
          {'─'.repeat(width)}
        </Text>
        <Text dimColor wrap="truncate-end">
          ◇ chapter · › sub-topic · ◆ breakpoint · {'>'} your prompt · ↳ Claude's answer · Enter opens · Esc closes
        </Text>
      </Box>
    )
  })
}

// ---- hooks/src/export.tsx

// The `exportDir` option, relative to the project root unless absolute.
let exportDirOption = EXPORT_DIR

async function exportSummary($: Dollar, title: string, exchanges: readonly ExportExchange[]): Promise<string> {
  const reply = await $.model.complete({ model: 'haiku', prompt: exportSummaryRequest(title, exchanges), maxTokens: 1200, timeoutMs: 90_000 })

  return reply.isAnswered ? reply.text.trim() : `_Summary unavailable (${reply.reason})._`
}

// `/bps export [n|words|all] [--summary]`: a chapter (the newest by default)
// or the whole conversation as markdown, prompts and final answers verbatim.
async function exportCommand($: Dollar, rest: string): Promise<CommandRunResult> {
  await syncSession($)
  const args = parseExportArgs(rest)
  const all = (await read($, marks)).filter(one => one.isRemoved !== true)
  const said = await read($, prompts)
  const scope = exportScope(args, all, said)
  if ('error' in scope) return { text: scope.error }

  const sessionId = await read($, session)
  const found = await readTranscript($, sessionId)
  const exchanges = scope.prompts.map(prompt => ({
    prompt,
    words: found.words.get(prompt.uuid) ?? prompt.text,
    answer: found.answers.get(prompt.uuid)?.text ?? '',
  }))
  const summary = args.withSummary ? await exportSummary($, scope.title, exchanges) : undefined
  const now = await $.clock.now()
  const markdown = exportMarkdown({ scope, all, said, exchanges, sessionId, exportedAt: now, ...(summary === undefined ? {} : { summary }) })

  const root = await $.session.root()
  const dir = exportDirectory(exportDirOption, root, (await $.env.get('HOME')) ?? '')
  let path = exportFileName(dir, scope.title, now, 1)
  for (let attempt = 2; attempt < 100 && (await $.fs.exists(path)); attempt += 1) {
    path = exportFileName(dir, scope.title, now, attempt)
  }
  await $.fs.write(path, markdown)

  const shown = path.startsWith(`${root}/`) ? path.slice(root.length + 1) : path
  const count = `${exchanges.length} exchange${exchanges.length === 1 ? '' : 's'}`

  return { text: `Exported "${scope.title}" (${count}${summary === undefined ? '' : ', with a summary'}) to ${shown}` }
}

// After a compaction of the main conversation, the outline stays in it: the
// model keeps the table of contents the summary may have flattened.
async function exportOnCompact(
  $: Dollar,
  e: SessionCompactInput,
  next: (e: SessionCompactInput) => Promise<SessionCompactResult>,
): Promise<SessionCompactResult> {
  const done = await next(e)
  if (done.skip !== undefined || e.agentId !== undefined || e.trigger === 'precompute') return done
  // The compaction itself becomes a breakpoint once its row is in the file.
  refreshEventsSoon($, 3000)

  try {
    await syncSession($)
    const outline = compactionOutline(
      (await read($, marks)).filter(one => one.isRemoved !== true),
      await read($, prompts),
    )

    return outline === null ? done : { ...done, messages: withOutline(done.messages, outline) }
  } catch (error) {
    $.ui.log(`breakpoints: could not keep the outline through compaction: ${String(error)}`, { to: 'debug' })

    return done
  }
}

// Export a chapter to markdown, and keep the outline through /compact.
const registerExport = (on: On, options: PluginOptions) => {
  exportDirOption = typeof options.exportDir === 'string' && options.exportDir.trim() !== '' ? options.exportDir : EXPORT_DIR

  on('command.run', { command: 'bps' }, async ($, e, next) => {
    const [word = '', ...rest] = squash(e.args).split(' ')

    return word.toLowerCase() === 'export' ? exportCommand($, rest.join(' ')) : next(e)
  })

  on('session.compact', ($, e, next) => exportOnCompact($, e, next))
}

// ---- hooks/src/pane.tsx

let paneOverflows = false

// The panel's keyboard toggle. A mod cannot add a keybinding action of its
// own; a Button can stand in for an engine action instead, and the person's
// key for that action presses it while it is drawn. This one only does
// anything in the diff panel, so outside it the key is free for ours.
// keybindings.json binds it (Global): "ctrl+x o": "app:toggleDiffNoiseFilter".
const PANE_TOGGLE_ACTION = 'app:toggleDiffNoiseFilter'
const PANE_TOGGLE_KEY = 'ctrl+x o'

const paneIsEditing = atom({ plugin: 'breakpoints', key: 'isEditing' } as const, false)
const paneRenaming = atom({ plugin: 'breakpoints', key: 'renaming' } as const, 0)

// Below this the panel drops the time and cost figures to keep the titles.
const PANE_STATS_WIDTH = 56

// Edit mode: a chapter renamed by hand keeps its name when labelling runs.
async function paneRename($: Dollar, id: number, value: string): Promise<void> {
  const label = clip(squash(value), 60)
  if (label !== '') {
    await update($, marks, list => list.map(one => (one.id === id ? { ...one, label, isRenamed: true } : one)))
    await persist($)
  }
  await update($, paneRenaming, () => 0)
  await statsRefreshStatus($)
}

// Merging a chapter takes its heading away: its exchanges join the chapter above.
async function paneMerge($: Dollar, id: number): Promise<void> {
  await update($, marks, list => list.map(one => (one.id === id ? { ...one, isRemoved: true } : one)))
  await persist($)
  await statsRefreshStatus($)
}

// A sub-topic becomes the first of a new chapter, named after it, and starts
// open. A heading merged away earlier at the same prompt is brought back
// rather than doubled.
async function paneSplit($: Dollar, prompt: BreakpointPrompt, title: string): Promise<void> {
  const at = await $.clock.now()
  let id = 0
  await update($, marks, list => {
    const earlier = list.find(one => one.kind === 'auto' && one.anchor === prompt.uuid)
    id = earlier?.id ?? nextId(list)
    if (earlier !== undefined) {
      return list.map(one => (one === earlier ? { ...one, label: title, isRenamed: true, isRemoved: false } : one))
    }
    const chapter: BreakpointMark = {
      id,
      kind: 'auto',
      label: title,
      anchor: prompt.uuid,
      anchorText: prompt.text,
      after: '',
      at,
      isRenamed: true,
    }

    return [...list, chapter]
  })
  // Only the last chapter starts open, and `toggled` flips the rest.
  const isLast = currentChapter(await read($, marks), await read($, prompts))?.id === id
  await update($, toggled, list => [...list.filter(one => one !== id), ...(isLast ? [] : [id])])
  await persist($)
  await statsRefreshStatus($)
}

async function paneOnStart($: Dollar): Promise<void> {
  await $.command.register({
    name: 'bp',
    description: 'Set a breakpoint at this point of the conversation',
    argumentHint: '[label]',
  })
  await $.command.register({
    name: 'bps',
    description: 'Outline of this conversation: jump, recall, fold, search past conversations, export',
    argumentHint: '[n | filter | search … | export … | fold … | unfold … | reading | redo]',
    immediate: true,
  })
}

// What was recalled rides along with the person's next message, unseen.
async function paneOnSubmit(
  $: Dollar,
  e: PromptSubmitInput,
  next: (e: PromptSubmitInput) => Promise<PromptSubmitResult>,
): Promise<PromptSubmitResult> {
  const isPersons = e.origin.kind === 'composer' || e.origin.kind === 'bridge'
  const pinned = isPersons && !e.text.trimStart().startsWith('/') ? await read($, recall) : []
  if (pinned.length === 0) return next(e)

  const entered = await next({ ...e, context: [...(e.context ?? []), ...pinned.map(one => one.text)] })
  if (entered.drop === undefined) await update($, recall, () => [])

  return entered
}

// Opens the panel, or closes it when it is up: the hint line's Outline
// button and the toggle key.
async function paneToggle($: Dollar): Promise<void> {
  if ((await $.ui.panes()).some(one => one.id === PANE)) {
    await $.ui.close({ id: PANE })

    return
  }
  await syncSession($)
  await update($, filter, () => '')
  await update($, isRecalling, () => false)
  await update($, paneRenaming, () => 0)
  await $.ui.open({ id: PANE, title: TITLE, focus: true, closeOnEscape: true })
}

const registerPane = (on: On) => {
  // The hint line under the prompt is always on screen: it carries the
  // Outline button, which the toggle key presses too.
  on('ui.render', { component: 'PromptHint' }, async ($, e, next) => {
    const { Box, Button } = $.ui.resolve(e)

    return (
      <Box flexDirection="row" gap={1}>
        <Box flexGrow={1}>{await next(e)}</Box>
        <Button key="bps-toggle" dimColor label="◇ Outline" action={PANE_TOGGLE_ACTION} onPress={() => paneToggle($)} />
      </Box>
    )
  })

  on('command.run', { command: 'bp' }, async ($, e) => {
    await syncSession($)
    const all = await read($, marks)
    const latest = (await read($, prompts)).at(-1)
    const id = nextId(all)
    const label = clip(squash(e.args), 80) || (latest ? clip(latest.title || latest.text, 60) : `Breakpoint ${id}`)
    const mark: BreakpointMark = {
      id,
      kind: 'manual',
      label,
      anchor: '',
      anchorText: '',
      after: latest?.uuid ?? '',
      at: await $.clock.now(),
    }

    await update($, marks, list => [...list, mark])
    await persist($)

    return { text: `◆ Breakpoint ${id} · ${label}` }
  })

  on('command.run', { command: 'bps' }, async ($, e) => {
    await syncSession($)

    later($, () => catchUp($))
    const args = squash(e.args)
    const isNumber = /^\d+$/.test(args)

    if (args === 'redo') {
      await resetOutline($)
      caughtUp.delete(await read($, session))
      later($, () => catchUp($))
      $.ui.toast('Redoing the outline of this conversation…')
    }

    if (isNumber) {
      // Command hints are not numbered: they live in the outline only.
      const live = (await read($, marks)).filter(one => one.isRemoved !== true && one.kind !== 'command')
      const mark = orderedMarks(live, await read($, prompts))[Number(args) - 1]

      if (mark !== undefined) {
        await jumpToMark($, mark, e.presentation.isFullscreen)

        return {}
      }
      $.ui.toast(`There is no entry ${args} in the breakpoints list.`)
    }

    await update($, filter, () => (isNumber || args === 'redo' ? '' : args))
    await update($, isRecalling, () => false)
    await update($, paneRenaming, () => 0)
    const opened = await $.ui.open({ id: PANE, title: TITLE, focus: true, closeOnEscape: true })

    if (!opened.isPlaced) {
      $.ui.toast(`The breakpoints list is waiting for room: ${opened.reason}`)
    } else if (paneOverflows && (await read($, tab)) !== 'marks') {
      await $.ui.scroll({ in: PANE, to: 'end' })
    }

    return {}
  })


  // What will ride along with the next message, above the prompt box.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const pinned = await read($, recall)
    if (pinned.length === 0 || e.props.hasSurvey) return next(e)

    const { Box, Text, Button } = $.ui.resolve(e)
    const size = pinned.reduce((sum, one) => sum + one.text.length, 0)
    const names = pinned.map(one => `${one.glyph} ${one.label} (${one.what})`).join(' · ')

    return (
      <Box flexDirection="row" gap={1}>
        <Text color="green" bold>
          ↩ Recalled for your next message:
        </Text>
        <Text wrap="truncate-end">{names}</Text>
        <Text dimColor>{`${Math.max(1, Math.round(size / 1000))}k chars`}</Text>
        <Box flexGrow={1} />
        <Button key="recall-drop" plain dimColor label="✕ drop" onPress={() => update($, recall, () => [])} />
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const elements = $.ui.resolve(e)
    const { Box, Text, Button } = elements
    const Input = 'Input' in elements ? elements.Input : undefined
    const said = await read($, prompts)
    const all = (await read($, marks)).filter(one => one.isRemoved !== true)
    const listed = orderedMarks(
      all.filter(one => one.kind !== 'command'),
      said,
    )
    const current = (await read($, tab)) === 'marks' ? 'marks' : 'outline'
    const query = (await read($, filter)).toLowerCase()
    const folded = await read($, toggled)
    const last = await read($, lastJump)
    const isAuto = await read($, auto)
    const working = await read($, busy)
    const picking = await read($, isRecalling)
    const editing = await read($, paneIsEditing)
    const renaming = await read($, paneRenaming)
    const now = await $.clock.now()
    const width = Math.max(24, e.props.bodyColumns)
    const hasStats = width >= PANE_STATS_WIDTH
    const isFullscreen = e.viewport?.isFullscreen
    const position = new Map(listed.map((mark, at) => [mark.id, at + 1]))
    const firstChapter = listed.find(one => one.kind === 'auto')
    const chapterAnchors = new Set(all.filter(one => one.kind === 'auto').map(one => one.anchor))

    const rows: OutlineRow[] =
      current === 'outline'
        ? query === ''
          ? buildOutline(all, said, folded)
          : filterOutline(all, said, query)
        : listed
            .filter(one => query === '' || one.label.toLowerCase().includes(query))
            .map(mark => ({ kind: 'mark' as const, mark, isNested: false }))
    paneOverflows = rows.length + 6 > e.props.scroll.bodyRows

    const line = (
      key: string,
      jumpKey: string,
      indent: number,
      glyph: string,
      color: string,
      label: string,
      age: string,
      onPress: () => void,
      extra: {
        hotkey?: string
        isDim?: boolean
        stats?: string
        lead?: RenderElement
        tail?: RenderElement
        tailWidth?: number
      } = {},
    ) => {
      const stats = hasStats ? (extra.stats ?? '') : ''
      const room = width - indent - age.length - (stats === '' ? 0 : stats.length + 3) - (extra.tailWidth ?? 0) - 10

      return (
        <Box key={`row-${key}`} flexDirection="row">
          <Text color={color}>
            {last === jumpKey ? '▸' : ' '}
            {' '.repeat(indent)}
          </Text>
          {extra.lead}
          <Text color={color}>{glyph} </Text>
          <Button
            key={key}
            plain
            {...(extra.isDim === true ? { dimColor: true } : {})}
            {...(extra.hotkey !== undefined ? { hotkey: extra.hotkey } : {})}
            label={clip(label, Math.max(8, room))}
            onPress={onPress}
          />
          <Box flexGrow={1} />
          {stats !== '' && <Text dimColor> {stats} ·</Text>}
          <Text dimColor> {age}</Text>
          {extra.tail}
        </Box>
      )
    }

    const removeButton = (mark: BreakpointMark) => (
      <Button
        key={`del-${mark.id}`}
        plain
        dimColor
        label=" ✕"
        onPress={async () => {
          await update($, marks, list => list.map(one => (one.id === mark.id ? { ...one, isRemoved: true } : one)))
          await persist($)
        }}
      />
    )

    // Edit mode on a chapter: rename it, or take its heading away. The first
    // chapter has none above to merge into, so its heading is just removed.
    const chapterTools = (mark: BreakpointMark) => (
      <Box key={`tools-${mark.id}`} flexDirection="row">
        <Button key={`rename-${mark.id}`} plain dimColor label=" rename" onPress={() => update($, paneRenaming, () => mark.id)} />
        <Button
          key={`merge-${mark.id}`}
          plain
          dimColor
          label={mark.id === firstChapter?.id ? ' ✕' : ' merge ↑'}
          onPress={() => paneMerge($, mark.id)}
        />
      </Box>
    )

    const renameRow = (mark: BreakpointMark) =>
      Input === undefined ? undefined : (
        <Box key={`row-rename-${mark.id}`} flexDirection="row">
          <Text color="cyan">  ◇ </Text>
          <Input key="rename" value={mark.label} submitLabel="Save" autoFocus onSubmit={value => paneRename($, mark.id, value)} />
          <Button key="rename-cancel" plain dimColor label=" cancel" onPress={() => update($, paneRenaming, () => 0)} />
        </Box>
      )

    const drawRow = (row: OutlineRow) => {
      if (row.kind === 'chapter') {
        const id = row.mark.id
        if (renaming === id && Input !== undefined) return renameRow(row.mark)

        const fold = (
          <Button
            key={`fold-${id}`}
            plain
            dimColor
            label={row.isOpen ? '▾' : '▸'}
            onPress={() => update($, toggled, list => (list.includes(id) ? list.filter(one => one !== id) : [...list, id]))}
          />
        )
        const count = row.isOpen || row.sections === 0 ? '' : ` (${row.sections})`

        return line(
          `c-${id}`,
          `mark:${id}`,
          0,
          ' ◇',
          'cyan',
          `${row.mark.label}${count}`,
          ago(now - row.mark.at),
          () => (picking ? recallRow($, row) : jumpToMark($, row.mark, isFullscreen)),
          {
            lead: fold,
            stats: formatStats(chapterTotal(row.mark, all, said)),
            ...(editing ? { tail: chapterTools(row.mark), tailWidth: 16 } : {}),
          },
        )
      }
      if (row.kind === 'section') {
        const canSplit = editing && !chapterAnchors.has(row.prompt.uuid)

        return line(
          `s-${row.prompt.n}`,
          `prompt:${row.prompt.uuid}`,
          row.isNested ? 3 : 0,
          '›',
          'white',
          row.title,
          ago(now - row.prompt.at),
          () => (picking ? recallRow($, row) : jumpToPrompt($, row.prompt, isFullscreen)),
          {
            isDim: row.prompt.isLabelled !== true,
            stats: formatStats(sectionTotal(row.prompt, all, said)),
            ...(canSplit
              ? {
                  tail: (
                    <Button
                      key={`split-${row.prompt.n}`}
                      plain
                      dimColor
                      label=" split here"
                      onPress={() => paneSplit($, row.prompt, row.title)}
                    />
                  ),
                  tailWidth: 11,
                }
              : {}),
          },
        )
      }
      if (row.kind === 'answer') {
        return line(
          `a-${row.prompt.n}`,
          `answer:${row.prompt.uuid}`,
          row.isNested ? 5 : 2,
          '↳',
          'green',
          row.title,
          '',
          () => (picking ? recallRow($, row) : jumpToAnswer($, row.prompt, isFullscreen)),
          { isDim: true },
        )
      }

      if (row.mark.kind === 'auto' && renaming === row.mark.id && Input !== undefined) return renameRow(row.mark)

      const number = position.get(row.mark.id) ?? 0
      const isFlat = current === 'marks'
      const hasHotkey = isFlat && number >= 1 && number <= 9
      const isStar = row.mark.kind === 'star'
      // A star sits under the answer it stars.
      const indent = isFlat ? 0 : isStar ? (row.isNested ? 7 : 4) : row.isNested ? 3 : 0

      return line(
        `m-${row.mark.id}`,
        `mark:${row.mark.id}`,
        indent,
        MARK_GLYPH[row.mark.kind],
        MARK_COLOR[row.mark.kind],
        isFlat && !hasHotkey ? `${number}: ${row.mark.label}` : row.mark.label,
        ago(now - row.mark.at),
        () => (picking ? recallRow($, row) : jumpToMark($, row.mark, isFullscreen)),
        {
          ...(hasHotkey ? { hotkey: String(number) } : {}),
          ...(row.mark.kind === 'command' ? { isDim: true } : {}),
          tail: removeButton(row.mark),
          tailWidth: 2,
        },
      )
    }

    const empty =
      query !== ''
        ? `Nothing matches "${query}".`
        : current === 'marks'
          ? 'No breakpoints yet. Type /bp to mark the latest point, or /bp <label> to name it.'
          : 'Nothing in this conversation yet.'

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Button
            key="tab-outline"
            hotkey="o"
            variant={current === 'outline' ? 'primary' : 'secondary'}
            label="Outline"
            onPress={async () => {
              await update($, tab, () => 'outline')
              if (paneOverflows) await $.ui.scroll({ in: PANE, to: 'end' })
            }}
          />
          <Button
            key="tab-marks"
            hotkey="b"
            variant={current === 'marks' ? 'primary' : 'secondary'}
            label={`Breakpoints ${listed.length}`}
            onPress={() => update($, tab, () => 'marks')}
          />
          {current === 'outline' && (
            <Button
              key="fold-all"
              hotkey="f"
              dimColor
              label="Fold all"
              onPress={() =>
                update($, toggled, () => {
                  const chapters = buildOutline(all, said, [], true).flatMap(row => (row.kind === 'chapter' ? [row.mark.id] : []))
                  const lastChapter = chapters.at(-1)

                  return lastChapter === undefined ? [] : [lastChapter]
                })
              }
            />
          )}
          <Button
            key="recall-mode"
            hotkey="r"
            variant={picking ? 'primary' : 'secondary'}
            label={picking ? 'Recall: pick one' : 'Recall'}
            onPress={() => update($, isRecalling, value => !value)}
          />
          <Button
            key="edit-mode"
            hotkey="e"
            variant={editing ? 'primary' : 'secondary'}
            label="Edit"
            onPress={async () => {
              await update($, paneIsEditing, value => !value)
              await update($, paneRenaming, () => 0)
            }}
          />
          <Button
            key="auto"
            hotkey="a"
            dimColor={!isAuto}
            label={`Auto ${isAuto ? 'on' : 'off'}`}
            onPress={async () => {
              const isOn = await update($, auto, value => !value)
              await $.store.set(AUTO, isOn)
              await statsRefreshStatus($)
              if (isOn) enqueue($, () => labelPending($, new Map()))
            }}
          />
          {query !== '' && (
            <Button
              key="clear-filter"
              hotkey="x"
              dimColor
              label={`× ${clip(query, 16)}`}
              onPress={() => update($, filter, () => '')}
            />
          )}
          <Box flexGrow={1} />
          <Button
            key="close"
            role="dismiss"
            hotkey="q"
            dimColor
            label="Close"
            action={PANE_TOGGLE_ACTION}
            onPress={() => $.ui.close({ id: PANE })}
          />
        </Box>
        <Text dimColor wrap="truncate-end">
          {'─'.repeat(width)}
        </Text>
        {picking && (
          <Text color="green" wrap="wrap">
            ↩ Pick what to bring back: it rides along, word for word, with your next message. r cancels.
          </Text>
        )}
        {editing && (
          <Text color="cyan" wrap="wrap">
            ✎ Rename or merge a chapter, or split one at a sub-topic. e ends.
          </Text>
        )}
        {working !== '' && <Text color="cyan">◇ {working}</Text>}
        {rows.length === 0 && <Text dimColor>{empty}</Text>}
        {rows.map(drawRow)}
        <Text dimColor wrap="truncate-end">
          {'─'.repeat(width)}
        </Text>
        <Text dimColor wrap="truncate-end">
          {`◇ chapter · › sub-topic · ↳ answer · ☆ starred · ◆ your /bp · ⇊ compacted · ⌘ command · Enter jumps · r recalls · e edits · Esc or ${PANE_TOGGLE_KEY} closes`}
        </Text>
      </Box>
    )
  })
}

// ---- hooks/src/main.tsx

// The engine allows one matcher-less hook per event per plugin, and follows
// `$` only into functions named at the top of the file. So the events several
// modules need are hooked here once, each module's part a named call. Hooks
// with a matcher (a render site, `/bps <word>`) live in the modules; for one
// shared matcher the first registered answers first, which is why the panel,
// whose /bps takes every argument the others pass on, registers last.
export const register: Register = (on, options) => {
  registerTracking(on)
  registerTranscript(on)
  registerStats(on)
  registerSearch(on)
  registerExport(on, options)
  registerPane(on)

  on('session.start', async ($, e, next) => {
    await trackingOnStart($)
    await transcriptOnStart($)
    await paneOnStart($)
    await statsOnStart($)

    return next(e)
  })

  on('session.end', async ($, e, next) => {
    const ended = await next(e)
    trackingOnEnd($, e)

    return ended
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    trackingOnTurn($, e)
    statsOnTurn($, e)

    return done
  })

  on('prompt.submit', ($, e, next) => paneOnSubmit($, e, next))
}
